#include "display.c"

static sensors_snapshot_t readings;
static uint8_t captured_pages[8][128];
static bool page_seen[8];
static uint32_t dashboard_time;

static bool capture_page(sh1106_send_t send, uint8_t address, uint8_t page,
                         const uint8_t *pixels, int cmock_num_calls)
{
    (void)send;
    (void)address;
    (void)cmock_num_calls;
    if ((page < 8U) && (pixels != NULL))
    {
        memcpy(captured_pages[page], pixels, sizeof(captured_pages[page]));
        page_seen[page] = true;
    }
    return true;
}

static void assert_glyph(uint8_t page, uint8_t column, unsigned char character)
{
    TEST_ASSERT_TRUE(page < 8U);
    TEST_ASSERT_TRUE(column < 21U);
    TEST_ASSERT_TRUE(page_seen[page]);
    TEST_ASSERT_EQUAL_UINT8_ARRAY(display_font[character - 32U],
                                  &captured_pages[page][(uint16_t)column * 6U], 6U);
}

static void assert_text(uint8_t page, const char *text)
{
    uint8_t column = 0U;
    while ((column < 21U) && (text[column] != '\0'))
    {
        unsigned char character = (unsigned char)text[column];
        if ((character < 32U) || (character > 126U))
        {
            character = (unsigned char)'?';
        }
        assert_glyph(page, column, character);
        column++;
    }
}

static void enter_dashboard(void)
{
    const uint32_t stabilization_time = 1000000U;

    /* Finish stabilization and transfer the splash logo.  The mocked clock
     * returns zero when the splash start time is recorded. */
    display_process(stabilization_time, &readings);
    dashboard_time = stabilization_time + LOGO_DISPLAY_MS;
    display_process(dashboard_time, &readings);
    for (uint8_t page = 1U; page < 8U; page++)
    {
        display_process(dashboard_time, &readings);
    }
}

static void render_dirty_dashboard(void)
{
    display_process(dashboard_time, &readings);
    for (uint8_t page = 1U; page < 8U; page++)
    {
        display_process(dashboard_time, &readings);
    }
}

