void test_display_01(void)
{
    char output[16];
    char small_output[3];

    display_value(output, sizeof(output), 12.34F, true);
    TEST_ASSERT_EQUAL_STRING("12.3", output);

    display_value(output, sizeof(output), -0.05F, true);
    TEST_ASSERT_EQUAL_STRING("-0.1", output);

    display_value(output, sizeof(output), 1000.0F, true);
    TEST_ASSERT_EQUAL_STRING("1000.0", output);

    display_value(output, sizeof(output), 1000.1F, true);
    TEST_ASSERT_EQUAL_STRING("--", output);
    display_value(output, sizeof(output), 1.0F, false);
    TEST_ASSERT_EQUAL_STRING("--", output);
    display_value(output, sizeof(output), NAN, true);
    TEST_ASSERT_EQUAL_STRING("--", output);
    display_value(output, sizeof(output), INFINITY, true);
    TEST_ASSERT_EQUAL_STRING("--", output);

    small_output[0] = 'X';
    small_output[1] = 'X';
    small_output[2] = '\0';
    display_value(small_output, sizeof(small_output), 12.34F, true);
    TEST_ASSERT_EQUAL_STRING("12", small_output);

    /* A zero-capacity snprintf destination must not be written. */
    output[0] = 'Q';
    display_value(output, 0U, 5.0F, true);
    TEST_ASSERT_EQUAL_INT('Q', output[0]);
}

void test_display_02(void)
{
    char expected[32];

    readings.climate_valid = true;
    readings.temperature_c = (float)TEMPERATURE_HIGH_C;
    readings.humidity_percent = (float)HUMIDITY_HIGH_PERCENT;
    readings.acceleration_valid = true;
    readings.acceleration.x_g = 1.0F;
    readings.acceleration.y_g = -2.0F;
    readings.acceleration.z_g = 3.0F;

    enter_dashboard();

    (void)snprintf(expected, sizeof(expected), "Temp:%d.0 degC", TEMPERATURE_HIGH_C);
    assert_text(1U, expected);
    (void)snprintf(expected, sizeof(expected), "Humidity:%d.0 %%", HUMIDITY_HIGH_PERCENT);
    assert_text(2U, expected);
    assert_text(5U, "X:1.0");
    assert_text(6U, "Y:-2.0");
    assert_text(7U, "Z:3.0 g");

    /* The source uses strict greater-than comparisons for both alert markers. */
    readings.temperature_c = (float)TEMPERATURE_HIGH_C + 1.0F;
    readings.humidity_percent = (float)HUMIDITY_HIGH_PERCENT + 1.0F;
    display_set_event("R");
    render_dirty_dashboard();
    (void)snprintf(expected, sizeof(expected), "Temp:%d.0 degC!", TEMPERATURE_HIGH_C + 1);
    assert_text(1U, expected);
    (void)snprintf(expected, sizeof(expected), "Humidity:%d.0 %%!", HUMIDITY_HIGH_PERCENT + 1);
    assert_text(2U, expected);

    /* Invalid readings take the display_value placeholder path and suppress
     * the alert suffix even when stored values exceed the configured limits. */
    readings.climate_valid = false;
    readings.acceleration_valid = false;
    readings.temperature_c = (float)TEMPERATURE_HIGH_C + 2.0F;
    readings.humidity_percent = (float)HUMIDITY_HIGH_PERCENT + 2.0F;
    display_set_event("S");
    render_dirty_dashboard();
    assert_text(1U, "Temp:-- degC");
    assert_text(2U, "Humidity:-- %");
    assert_text(5U, "X:--");
    assert_text(6U, "Y:--");
    assert_text(7U, "Z:-- g");
}

void test_display_03(void)
{
    char event[43];
    uint8_t zero_page[128] = {0};

    enter_dashboard();

    memset(event, 'B', 42U);
    event[0] = 'A';
    event[1] = '\x01';
    event[20] = 'Y';
    event[21] = 'Z';
    event[41] = '!';
    event[42] = '\0';
    display_set_event(event);
    render_dirty_dashboard();

    /* display_text renders at most 21 glyphs on each event row, replacing
     * control bytes with '?'; the 22nd through 42nd bytes occupy row four. */
    assert_glyph(3U, 0U, 'A');
    assert_glyph(3U, 1U, '?');
    assert_glyph(3U, 20U, 'Y');
    assert_glyph(4U, 0U, 'Z');
    assert_glyph(4U, 20U, '!');

    display_set_event(NULL);
    render_dirty_dashboard();
    TEST_ASSERT_EQUAL_UINT8_ARRAY(zero_page, captured_pages[3], sizeof(zero_page));
    TEST_ASSERT_EQUAL_UINT8_ARRAY(zero_page, captured_pages[4], sizeof(zero_page));

    /* An empty event is the zero-length text case: it draws neither event row. */
    display_set_event("");
    render_dirty_dashboard();
    TEST_ASSERT_EQUAL_UINT8_ARRAY(zero_page, captured_pages[3], sizeof(zero_page));
    TEST_ASSERT_EQUAL_UINT8_ARRAY(zero_page, captured_pages[4], sizeof(zero_page));
}
